table = {}

def insert_entity(partition_key, row_key, properties):
    table[(partition_key, row_key)] = properties

def query_partition(partition_key):
    return sorted(
        (row_key, props) for (pk, row_key), props in table.items() if pk == partition_key
    )

insert_entity("device:sensor01", "2026-01-01T00:00", {"temp": 21.5})
insert_entity("device:sensor01", "2026-01-01T01:00", {"temp": 21.8})
insert_entity("device:sensor02", "2026-01-01T00:00", {"temp": 19.2})

for row_key, props in query_partition("device:sensor01"):
    print(row_key, props)
print("total entities:", len(table))
